{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/icon-wall.json
    A dense grid of small tiles: an icon and a short label. Axes: columns (3, 4, 6), item (tile: icon above the label, chip: icon beside it), tone, density.
    Props (p): id, title, features, empty, cols, item, tone, density, landmarkLabel. -#}
{%- set v_id = og_def(p['id'], none) -%}
{%- set v_title = og_def(p['title'], none) -%}
{%- set v_features = og_def(p['features'], none) -%}
{%- set v_empty = og_def(p['empty'], '') -%}
{%- set v_cols = og_def(p['cols'], '4') -%}
{%- set v_item = og_def(p['item'], 'tile') -%}
{%- set v_tone = og_def(p['tone'], 'default') -%}
{%- set v_density = og_def(p['density'], 'default') -%}
{%- set v_landmarkLabel = og_def(p['landmarkLabel'], none) -%}
{%- set v_askedCols = ('2-6' if og_t(og_and([og_eq(v_item, 'chip'), og_eq(v_cols, '6')])) else ('2' if og_t(og_eq(v_cols, '2')) else ('2-3' if og_t(og_eq(v_cols, '3')) else ('2-4' if og_t(og_eq(v_cols, '4')) else '3-6')))) -%}
{%- set v_wallCols = og_fit_cols(v_askedCols, og_len(v_features)) -%}
{%- set c_4 -%}
  {%- if og_t(og_eq(og_len(v_features), 0)) %}
    {{ og_include('blocks/empty-state.html.j2', {'p': {'icon': 'layout-grid', 'title': v_empty}}) }}
  {%- else %}
    {%- set c_3 -%}
      {%- for v_f in og_l(v_features) %}
        {%- set c_2 -%}
          {{ og_include('icons/lucide-icon.html.j2', {'p': {'Name': og_s(og_get(v_f, ['icon'])), 'Size': og_i((24 if og_t(og_eq(v_item, 'tile')) else 16))}}) }}
          {%- set c_1 -%}
            {{ og_text(og_get(v_f, ['title'])) }}
          {%- endset -%}
          {{ og_include('compose/text.html.j2', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_1}) }}
        {%- endset -%}
        {{ og_include('compose/box.html.j2', {'p': {'Class': og_s(og_cnv(['flex items-center gap-2', 'rounded bg-card inset-ring inset-ring-border', (og_cnv(['flex-col justify-center text-center', ('p-4' if og_t(og_eq(v_density, 'compact')) else 'p-6')]) if og_t(og_eq(v_item, 'tile')) else 'px-4 py-2')])), 'Attrs': og_attrs(['data-testid', 'item'])}, 'children': c_2}) }}
      {%- endfor %}
    {%- endset -%}
    {{ og_include('compose/grid.html.j2', {'p': {'Cols': og_s(v_wallCols), 'Class': 'gap-4', 'Attrs': og_attrs(['data-testid', 'items'])}, 'children': c_3}) }}
  {%- endif %}
{%- endset -%}
{{ og_include('blocks/section-frame.html.j2', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}, 'children': og_markup(c_4)}) }}
